(947440, 110554, 18799, '<td valign="top">Good  eye!  I like this one a lot.  Good Luck!</td>', 'Good  eye!  I like this one a lot.  Good Luck!', '2004-10-07 02:48:03.000000', NULL, 1),
(947441, 110127, 12813, '<td valign="top">Lol funny</td>', 'Lol funny', '2004-10-07 02:48:17.000000', NULL, 1),
(947442, 110387, 14476, '<td valign="top">Excellent composition, good color.  I understand your soft focus, but would love to also see the cannon in sharp focus.</td>', 'Excellent composition, good color.  I understand your soft focus, but would love to also see the cannon in sharp focus.', '2004-10-07 02:48:35.000000', NULL, 1),
(947444, 110350, 18799, '<td valign="top">Has to be sharper</td>', 'Has to be sharper', '2004-10-07 02:48:40.000000', NULL, 1),
(947445, 109275, 20330, '<td valign="top">I love this one. Was thinking of doing the same with my cat but went another direction. I love the texture in the tongue and the cropping. 9</td>', 'I love this one. Was thinking of doing the same with my cat but went another direction. I love the texture in the tongue and the cropping. 9', '2004-10-07 02:49:01.000000', NULL, 1),
(947448, 110376, 14476, '<td valign="top">Lovely color and pretty good focus.  You''ve presented quite a lot of information here, and it would be interesting to see the result if you zeroed in on just part of the subject.</td>', 'Lovely color and pretty good focus.  You''ve presented quite a lot of information here, and it would be interesting to see the result if you zeroed in on just part of the subject.', '2004-10-07 02:50:08.000000', NULL, 1),
