(947461, 110468, 12813, '<td valign="top">sweet. nice title (can relate)</td>', 'sweet. nice title (can relate)', '2004-10-07 03:01:56.000000', NULL, 1),
(947464, 110241, 18461, '<td valign="top">Nice composition and lighting.</td>', 'Nice composition and lighting.', '2004-10-07 03:02:48.000000', NULL, 1),
