(953402, 110567, 25464, '<td valign="top">I like the creative composition.</td>', 'I like the creative composition.', '2004-10-10 22:52:50.000000', NULL, 1),
(953403, 110129, 26757, '<td valign="top">Very nice.  I was glad to see that while you cropped in close, you were successful in not clipping out the tip of the earring.  Very nicely done.<br/>ginette</td>', 'Very nice.  I was glad to see that while you cropped in close, you were successful in not clipping out the tip of the earring.  Very nicely done.ginette', '2004-10-10 22:52:54.000000', NULL, 1),
(953409, 110516, 26757, '<td valign="top">Interesting light fall onto the stucco, composition.  I think I might have liked to have been able to see a bit more detail in the stucco, especially at the lower left... But very nice.</td>', 'Interesting light fall onto the stucco, composition.  I think I might have liked to have been able to see a bit more detail in the stucco, especially at the lower left... But very nice.', '2004-10-10 22:58:20.000000', NULL, 1),
(953415, 110522, 26757, '<td valign="top">Too broad of a view I think, for parts, but still a beautiful image.<br/>ginette</td>', 'Too broad of a view I think, for parts, but still a beautiful image.ginette', '2004-10-10 22:59:53.000000', NULL, 1),
(953418, 109542, 26757, '<td valign="top">Such potential!  Needs work on the lighting so that there is more detail in the digit prints...  Needs more variance of coloration... <br/>ginette</td>', 'Such potential!  Needs work on the lighting so that there is more detail in the digit prints...  Needs more variance of coloration... ginette', '2004-10-10 23:01:56.000000', NULL, 1),
(953419, 110171, 26757, '<td valign="top">Great for a stock add for a jewwler!<br/>ginette</td>', 'Great for a stock add for a jewwler!ginette', '2004-10-10 23:03:22.000000', NULL, 1),
(953421, 110231, 26757, '<td valign="top">Needs a bti more intewrest.<br/>ginette</td>', 'Needs a bti more intewrest.ginette', '2004-10-10 23:04:04.000000', NULL, 1),
(953422, 110382, 10263, '<td valign="top">This is wonderful. Simple but striking.. Love the lighting on the tip.. 10</td>', 'This is wonderful. Simple but striking.. Love the lighting on the tip.. 10', '2004-10-10 23:04:12.000000', NULL, 1),
(953423, 110567, 15029, '<td valign="top">smudges in the upper left hand corner are distracting</td>', 'smudges in the upper left hand corner are distracting', '2004-10-10 23:05:26.000000', NULL, 1),
